create or replace function operations_private.hub_baseline_confirm_plan_v1(p_session_token text,p_request_id uuid,p_source text,p_export_job_id uuid,p_artifact_digest text,p_expected_version_id uuid,p_expected_version integer,p_plan_token text,p_operations jsonb,p_upload_confirmed boolean)
returns jsonb language plpgsql security definer set search_path=pg_catalog set lock_timeout='5s' set statement_timeout='60s' as $$
declare who text; plan operations_private.hub_baseline_export_plans%rowtype; receipt operations_private.hub_baseline_artifact_receipts%rowtype; prior operations_private.hub_baseline_commits%rowtype; head uuid; number integer; new_id uuid; ops jsonb;
begin
 who:=operations_private.require_operations_hub_operator_session(p_session_token)->>'username';
 if p_request_id is null or p_upload_confirmed is distinct from true then raise exception 'explicit upload confirmation required';end if;
 perform pg_advisory_xact_lock(hashtextextended('hub-baseline-commit:'||p_request_id,0));
 select * into plan from operations_private.hub_baseline_export_plans where export_job_id=p_export_job_id;
 if not found or plan.operator<>who or (plan.source,plan.expected_version_id,plan.expected_version) is distinct from (p_source,p_expected_version_id,p_expected_version) or plan.plan_token_hash is distinct from encode(extensions.digest(p_plan_token,'sha256'),'hex') or plan.blocked_count<>0 then raise exception 'invalid plan token/version/operator or BLOCK';end if;
 perform pg_advisory_xact_lock(hashtextextended('hub-baseline-plan-commit:'||plan.id,0));
 select * into receipt from operations_private.hub_baseline_artifact_receipts where plan_id=plan.id;
 if not found or not receipt.serializer_success or receipt.artifact_digest is distinct from p_artifact_digest or receipt.applied_operations is distinct from p_operations then raise exception 'sealed serializer receipt mismatch';end if;
 ops:=operations_private.hub_canary_operations_v1(p_source,p_expected_version_id,p_operations,true);
 if ops is distinct from plan.operations then raise exception 'commit operation set mismatch';end if;
 select * into prior from operations_private.hub_baseline_commits where request_id=p_request_id;
 if found and prior.plan_id<>plan.id then raise exception 'request id reused for another export job';end if;
 if not found then select * into prior from operations_private.hub_baseline_commits where plan_id=plan.id;end if;
 if found then
  if prior.plan_id<>plan.id or prior.operator<>who then raise exception 'export job/request already committed with other identity';end if;
  return jsonb_build_object('version_id',prior.new_version_id,'previous_version_id',prior.previous_version_id,'version',(select version from operations_private.hub_baseline_versions where id=prior.new_version_id),'reused',true,'committed_request_id',prior.request_id,'operation_count',prior.operation_count);
 end if;
 select h.current_version_id,v.version into head,number from operations_private.hub_baseline_heads h join operations_private.hub_baseline_versions v on v.id=h.current_version_id where h.source=p_source for update of h;
 if head is distinct from p_expected_version_id or number is distinct from p_expected_version then raise exception 'stale baseline CAS conflict';end if;
 if jsonb_array_length(ops)=0 then new_id:=head;
 else
  insert into operations_private.hub_baseline_versions(source,version,previous_version_id,export_job_id,request_id,event,operation_count,confirmed_at,created_by) values(p_source,number+1,head,p_export_job_id,p_request_id,'confirmed_plan',jsonb_array_length(ops),clock_timestamp(),who) returning id into new_id;
  insert into operations_private.hub_baseline_rows(version_id,product_code,option_code,facts,source_row_no,source_file_name)
  select new_id,b.product_code,b.option_code,jsonb_set(jsonb_set(b.facts,'{stock}',coalesce((select x->'effective_target' from jsonb_array_elements(ops) x where x->>'product_code'=b.product_code and coalesce(x->>'option_code','')=b.option_code and x->>'field'='stock'),b.facts->'stock')),'{price}',coalesce((select x->'effective_target' from jsonb_array_elements(ops) x where x->>'product_code'=b.product_code and coalesce(x->>'option_code','')=b.option_code and x->>'field'='price'),b.facts->'price')),b.source_row_no,b.source_file_name from operations_private.hub_baseline_rows b where b.version_id=head;
  update operations_private.hub_baseline_heads set current_version_id=new_id where source=p_source and current_version_id=head;
  if not found then raise exception 'baseline CAS conflict';end if;
 end if;
 insert into operations_private.hub_baseline_commits(request_id,plan_id,previous_version_id,new_version_id,artifact_digest,operation_count,operator) values(p_request_id,plan.id,head,new_id,p_artifact_digest,jsonb_array_length(ops),who);
 update public.operations_hub_export_jobs set phase='baseline_committed',updated_at=clock_timestamp(),snapshot=coalesce(snapshot,'{}'::jsonb)||jsonb_build_object('baseline_version_id',new_id,'baseline_confirmed_at',clock_timestamp()) where job_id=plan.export_job_id;
 return jsonb_build_object('version_id',new_id,'previous_version_id',head,'version',case when new_id=head then number else number+1 end,'reused',false,'operation_count',jsonb_array_length(ops));
end $$;
